INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) SELECT 'ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', concepto, enseñanza, ejemplo, NULL, NULL, NULL, orden FROM (VALUES ('La Reducción de Tickets de Soporte – El Beneficio Oculto', 'Al validar técnicamente el local antes de la instalación, INVU evita el 80% de los problemas que generan tickets de soporte en los primeros días. Esto significa clientes más satisfechos, menos llamadas de emergencia, y una experiencia de marca impecable desde el día uno. El Hunter debe comunicar que la visita técnica es una inversión en tranquilidad.', '"La mayoría de los problemas que tienen los clientes de otros POS son por falta de validación técnica: internet lento, hardware incompatible, mala ubicación de equipos. Nosotros prevenimos eso antes de la instalación, para que no tengas sorpresas después. La visita técnica es tu garantía de que el sistema funcionará sin problemas desde el día uno."', 31),
('La Visita Técnica como Argumento de Cierre', 'El informe técnico resultante de la visita es una herramienta poderosa para el cierre. El Hunter lo usa para armar una cotización precisa con costos de hardware justificados. El informe es un documento con peso técnico que demuestra al cliente que la inversión es necesaria y que INVU es un socio confiable.', 'Un cliente duda sobre la inversión en hardware. El Hunter presenta el informe: "Nuestro especialista validó que tu operación necesita X hardware para funcionar de manera óptima. Te recomendamos esta inversión para garantizar continuidad. Sin esto, tu sistema podría tener fallas en horas pico. Con esto, operas sin interrupciones." El cliente, al ver el informe técnico, acepta la inversión.', 32),
('La Pregunta Clave – ¿Qué Tipo de Internet Tienen?', 'El Hunter debe preguntar en el discovery: "¿Qué tipo de conexión a internet tienen y qué velocidad contratada?" Fibra óptica (FTTH) es recomendada; coaxial (HFC) genera latencia inestable. Esta pregunta permite al Hunter anticipar problemas y preparar al cliente para posibles mejoras.', 'Un Hunter pregunta: "¿Qué tipo de internet tienen?" El cliente responde: "Coaxial de 100MB." El Hunter sabe que esto puede ser problemático. Dice: "El coaxial puede generar latencia en horas pico. Nuestro especialista lo evaluará en la visita técnica y te recomendará si necesitas migrar a fibra óptica para garantizar estabilidad." El cliente valora la transparencia.', 33),
('La Pregunta Clave – ¿Qué Hardware Utilizan Actualmente?', 'El Hunter debe preguntar: "¿Qué equipos y hardware utilizan actualmente (marcas, modelos, antigüedad)?" Esto incluye impresoras, tablets, computadoras, lectores, cajones de dinero. Saber esto permite al Hunter dimensionar la reutilización de hardware y preparar al cliente para posibles reemplazos.', 'Un Hunter pregunta: "¿Qué tablets usan?" El cliente responde: "Tablets de 5 años." El Hunter dice: "Entiendo. Nuestro especialista evaluará si aún son funcionales o si necesitan reemplazo. Si funcionan, las reutilizamos; si no, te recomendamos nuevas." El cliente se siente escuchado y confía en el proceso.', 34),
('La Pregunta Clave – ¿Tienen un Área de Cocina Separada?', 'El Hunter debe preguntar: "¿Tienen un área de cocina o producción separada? ¿Dónde se ubican las estaciones de venta?" Esto permite planificar la ubicación estratégica de los equipos (POS, KDS, impresoras de comandas) y garantizar la eficiencia operativa.', 'Un Hunter pregunta y descubre que la cocina está a 15 metros de la caja. Dice: "Perfecto. Nuestro especialista evaluará la mejor ubicación para la impresora de comandas y la pantalla KDS. Así los pedidos llegan rápido a cocina y tu personal no pierde tiempo." El cliente valora que el Hunter esté pensando en su flujo de trabajo.', 35),
('La Pregunta Clave – ¿Manejan Delivery o Apps?', 'El Hunter debe preguntar: "¿Manejan delivery o integraciones con apps como Rappi o PedidosYa?" Si el cliente tiene alta demanda de delivery, necesita un enlace de internet más estable y un router con respaldo 4G. Esta pregunta permite al Hunter anticipar necesidades de hardware crítico.', 'El cliente responde: "Sí, movemos S/10,000 al mes por delivery." El Hunter dice: "Excelente. Entonces tu internet debe ser muy estable y tener respaldo. Nuestro especialista evaluará tu red y te recomendará un router 4G de respaldo para que nunca pierdas una venta de delivery." El cliente ve el valor inmediato.', 36),
('El Framework Gravity Aplicado a Hardware – Diagnóstico', 'El Hunter debe hacer las preguntas de diagnóstico sobre hardware y red durante el discovery o la demo. No debe esperar a la visita técnica para descubrir problemas. El diagnóstico temprano permite preparar al cliente y al especialista técnico, y posiciona al Hunter como un consultor proactivo.', 'En el discovery, el Hunter pregunta sobre internet, hardware y distribución. Al identificar que el cliente tiene coaxial y tablets viejas, dice: "Nuestro especialista evaluará esto en la visita técnica. Te anticipo que podríamos recomendar migrar a fibra óptica y renovar algunas tablets. Pero no te preocupes, evaluaremos todo y te daremos un informe con prioridades."', 37),
('El Framework Gravity Aplicado a Hardware – Educación', 'El Hunter educa al cliente sobre la importancia de la visita técnica: "Nuestro especialista va a evaluar tu red, hardware y distribución para asegurarse de que la implementación sea 100% exitosa. Esto es parte de nuestro modelo llave en mano. No te dejamos solo con el software; validamos tu infraestructura para que no tengas sorpresas." La educación es clave para que el cliente vea la visita como un valor agregado.', 'Un cliente dice: "No sé si necesito la visita técnica." El Hunter responde: "Es parte de nuestro servicio. No queremos que instales el sistema y descubras que tu internet es lento o que tu hardware no es compatible. Preferimos validar todo antes, para que desde el día uno estés operando sin interrupciones."', 38),
('El Framework Gravity Aplicado a Hardware – Comparación', 'El Hunter compara con la competencia: "Otros sistemas te entregan el software y tú te las arreglas para que funcione. Si tu internet es lento o tu hardware no es compatible, te das cuenta después de la instalación y pierdes días resolviendo problemas. INVU valida todo antes, para que desde el día uno estés operando sin interrupciones." Esta comparación posiciona a INVU como el socio confiable.', 'El cliente dice: "Mi amigo tiene otro POS y no necesitó visita técnica." El Hunter responde: "Y probablemente tuvo problemas los primeros días. Nosotros preferimos prevenir. La visita técnica es lo que nos diferencia: validamos tu infraestructura antes de instalar, para que no tengas sorpresas."', 39),
('El Framework Gravity Aplicado a Hardware – Construcción de Valor', 'El Hunter construye valor mostrando los beneficios de la visita técnica: "Con esta evaluación, aseguramos que tu sistema funcione sin caídas, que tu hardware sea el adecuado, que tu personal pueda operar sin frustraciones, y que puedas seguir vendiendo incluso si el internet falla gracias al respaldo 4G. No es un gasto, es una inversión en la continuidad de tu negocio." El valor es la tranquilidad operativa.', '"Imagina que un viernes a las 8pm, en pleno horario pico, el internet se cae. Con el respaldo 4G, tu sistema sigue operando. Esa es la tranquilidad que te da la visita técnica. No perderás una venta por un corte de internet."', 40),
('El Framework Gravity Aplicado a Hardware – Cierre', 'El Hunter cierra la agenda de la visita técnica: "¿Qué día te acomoda que nuestro especialista vaya a tu local para hacer la evaluación? Es sin costo para ti y te daremos un informe con recomendaciones personalizadas." El cierre es asegurar la visita, que es el paso previo a la cotización y el cierre final.', 'Después de presentar el valor de la visita técnica, el Hunter dice: "¿Qué te parece si agendamos la visita para el próximo martes? El especialista irá a tu local, hará la evaluación, y te dará un informe. Sin compromiso. Después decides qué hardware renovar." El cliente acepta y el Hunter agenda la visita.', 41),
('El Manejo de la Objeción "No Quiero Invertir en Hardware Nuevo"', 'El cliente que dice "no quiero invertir en hardware nuevo" está preocupado por el costo. El Hunter debe validar, educar sobre la reutilización de hardware, comparar con la competencia (que obliga a comprar todo nuevo), y construir valor mostrando que la inversión se paga sola con la eficiencia ganada.', '"Entiendo. Por eso hacemos la visita técnica: para evaluar qué se puede reutilizar y qué necesita reemplazo. Nuestro especialista te dirá con honestidad qué equipos aún sirven y cuáles te están generando pérdidas de tiempo y dinero. No te vamos a vender algo que no necesites. Y la inversión en hardware nuevo se paga sola con la eficiencia que ganas."', 42),
('El Manejo de la Objeción "¿Por qué Tengo que Pagar por la Visita Técnica?"', 'El cliente que pregunta por el costo de la visita técnica debe ser informado de que es gratuita y parte del modelo llave en mano. El Hunter debe comunicar que la visita técnica es una inversión de INVU para asegurar el éxito del cliente, no un costo adicional.', '"La visita técnica es gratuita para ti. Es parte de nuestro modelo llave en mano. No te cobramos por la evaluación, la incluimos en el setup. Queremos asegurarnos de que tu implementación sea 100% exitosa desde el día uno. No es un gasto, es una inversión nuestra en tu éxito."', 43),
('Los Niveles de Dominio en Hardware y Visita Técnica', 'El Hunter pasa por 4 niveles en el manejo de hardware y visita técnica: Básico (conoce el proceso pero no lo ejecuta proactivamente), Medio (ejecuta la visita como parte del proceso), Alto (usa la visita como herramienta de valor y upselling), y Gravedad Cero (integra la visita en su estrategia de consultoría, anticipa necesidades, y convierte cada visita en una oportunidad de venta adicional, incrementando el setup facturado en un 40% o más).', 'Básico: Sabe que existe la visita técnica, pero no la menciona hasta que el cliente pregunta.  
